window.SZKICE = {
 "uczen/L01_pierwszy_program": "/*\n * ==============================================================\n *  LEKCJA 01: PIERWSZY PROGRAM – SERIAL I DIODA\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 2\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Każdy program Arduino ma dwie części: setup() i loop().\n *   - Jak włączyć i wyłączyć diodę.\n *   - Jak płytka „pisze” do komputera (Serial Monitor).\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Tylko kabel USB. Dioda jest już na płytce.\n *\n *  JAK TO DZIAŁA\n *   setup() wykonuje się RAZ, zaraz po włączeniu.\n *   loop() wykonuje się w kółko, bez końca.\n *\n *      start\n *        |\n *     setup()        <- raz\n *        |\n *     loop()  <--+   <- w kółko\n *        |       |\n *        +-------+\n *\n *   SERIAL (UART) to rozmowa płytki z komputerem po kablu.\n *   Płytka wysyła bity (zera i jedynki) jeden po drugim,\n *   z prędkością 115200 bitów na sekundę. Komputer pokazuje\n *   je jako tekst w Serial Monitorze (lupa w prawym górnym rogu).\n *   Obie strony muszą „mówić” w tym samym tempie: 115200.\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Zmień tempo mrugania (TEMPO_MS).\n *   2. Zrób sygnał SOS:  ... --- ...  (3 krótkie, 3 długie, 3 krótkie).\n *   3. Wypisuj licznik mrugnięć w Serial Monitorze.\n */\n\n// ================== KONFIGURACJA ==================\n#ifdef RGB_BUILTIN\nconst int PIN_DIODY = RGB_BUILTIN;   // kolorowa dioda na płytce\n#else\nconst int PIN_DIODY = LED_BUILTIN;   // zwykła dioda na płytce\n#endif\n\n// ZADANIE 1: zmień tempo mrugania. 1000 ms = 1 sekunda.\n// Spróbuj 100, potem 2000. Co widzisz?\nconst int TEMPO_MS = 500;\n\n// ZADANIE 2 (część a): gdy funkcja sygnalSOS() będzie gotowa,\n// zmień false na true.\nconst bool TRYB_SOS = false;\n// ==================================================\n\nint licznik = 0;   // zmienna: pudełko na liczbę, która może się zmieniać\n\nvoid setup() {\n  Serial.begin(115200);   // otwieramy „rozmowę” z komputerem\n  delay(1000);            // chwila, żeby komputer zdążył się połączyć\n  pinMode(PIN_DIODY, OUTPUT);\n  Serial.println(\"Cześć! Tu dron. Zaczynam mrugać.\");\n}\n\n// Jedno mrugnięcie: włącz, poczekaj, wyłącz, poczekaj.\nvoid mrugnij(int czas_ms) {\n  digitalWrite(PIN_DIODY, HIGH);   // HIGH = włączona\n  delay(czas_ms);                  // delay = czekaj (w ms)\n  digitalWrite(PIN_DIODY, LOW);    // LOW = wyłączona\n  delay(czas_ms);\n}\n\n// ZADANIE 2 (część b): SOS = 3 krótkie, 3 długie, 3 krótkie.\n// Na razie są tylko 3 krótkie. Dopisz resztę.\n// Podpowiedź: pętla for powtarza coś kilka razy:\n//   for (int i = 0; i < 3; i++) mrugnij(200);\nvoid sygnalSOS() {\n  for (int i = 0; i < 3; i++) mrugnij(200);   // S: kropki\n\n  delay(1500);                                // przerwa przed kolejnym SOS\n}\n\nvoid loop() {\n  // ZADANIE 3: zwiększ licznik o 1 i wypisz go, np.:\n  //   licznik = licznik + 1;\n  //   Serial.print(\"Mrugnięcie numer: \");\n  //   Serial.println(licznik);\n\n  if (TRYB_SOS) {\n    sygnalSOS();\n  } else {\n    mrugnij(TEMPO_MS);\n  }\n}\n",
 "uczen/L02_skaner_i2c": "/*\n * ==============================================================\n *  LEKCJA 02: SKANER I2C – KTO JEST NA MAGISTRALI?\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 2\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Co to jest I2C (czyt. „i kwadrat ce”).\n *   - Co to jest adres urządzenia.\n *   - Jak sprawdzić, czy czujniki są dobrze podłączone.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Na dronie: MPU6050 i laser VL53L1X (oba na tych samych 4 przewodach).\n *   - Kabel z drona (ok. 1 m) wpięty w płytkę stykową:\n *     czerwony = 3V3, czarny = GND, żółty = SDA -> pin 6,\n *     niebieski = SCL -> pin 7.\n *\n *  JAK TO DZIAŁA\n *   I2C to dwie wspólne linie dla wielu urządzeń:\n *     SDA – dane (tu jadą bity),\n *     SCL – zegar (mówi KIEDY czytać bit).\n *\n *     ESP32 ---SDA-----+-----------+----\n *           ---SCL---+-|---------+-|----\n *                    | |         | |\n *                 [MPU6050]   [laser]\n *                  adr 0x68   adr 0x29\n *\n *   Każde urządzenie ma ADRES – jak numer mieszkania w bloku.\n *   ESP „puka” pod adres i czeka na odpowiedź „jestem!”\n *   (to się nazywa ACK). Brak odpowiedzi = nikogo tam nie ma.\n *   Skaner puka po kolei pod adresy 1..126.\n *   Adresy piszemy szesnastkowo: 0x29 to 41, 0x68 to 104.\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Dopisz nazwę urządzenia dla adresu 0x68.\n *   2. Policz znalezione urządzenia i wypisz ich liczbę.\n *   3. Odłącz jeden czujnik (przy wyłączonym zasilaniu!)\n *      i uruchom skaner jeszcze raz. Co się zmieniło?\n */\n\n#include <Wire.h>\n\n// ================== KONFIGURACJA ==================\nconst int PIN_SDA = 6;\nconst int PIN_SCL = 7;\nconst int CO_ILE_MS = 5000;      // skanuj co 5 sekund\n// ==================================================\n\n// Zamienia adres na nazwę urządzenia.\nString nazwa(int adres) {\n  if (adres == 0x29) return \"laser VL53L1X (odległość)\";\n  // ZADANIE 1: dopisz podobną linijkę dla adresu 0x68.\n  // To czujnik MPU6050 (żyroskop i akcelerometr).\n\n  return \"nieznane urządzenie\";\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(1000);\n  Wire.begin(PIN_SDA, PIN_SCL);\n  Wire.setClock(100000);   // 100 kHz: kabel I2C ma ok. 1 m, więc wolniej i pewniej\n  Wire.setTimeOut(50);     // nie czekaj w nieskończoność, gdy czujnik milczy   // włączamy I2C na naszych pinach\n  Serial.println(\"L02: skaner I2C\");\n}\n\nvoid loop() {\n  Serial.println(\"Skanuję adresy 1..126 ...\");\n  int znalezione = 0;\n\n  for (int adres = 1; adres <= 126; adres++) {\n    Wire.beginTransmission(adres);        // „puk, puk” pod ten adres\n    int wynik = Wire.endTransmission();   // 0 = ktoś odpowiedział (ACK)\n    if (wynik == 0) {\n      Serial.print(\"  Znalazłem 0x\");\n      if (adres < 16) Serial.print(\"0\");\n      Serial.print(adres, HEX);\n      Serial.print(\"  ->  \");\n      Serial.println(nazwa(adres));\n      // ZADANIE 2 (część a): zwiększ tu znalezione o 1.\n    }\n  }\n\n  // ZADANIE 2 (część b): wypisz liczbę znalezionych urządzeń.\n\n  Serial.println();\n  delay(CO_ILE_MS);\n}\n",
 "uczen/L03_wysokosc": "/*\n * ==============================================================\n *  LEKCJA 03: POMIAR WYSOKOŚCI LASEREM\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 2\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Jak laser mierzy odległość („czas lotu światła”).\n *   - Jak używać gotowej biblioteki czujnika.\n *   - Kiedy pomiar jest dobry, a kiedy nie.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Laser VL53L1X na dronie, patrzy w dół na podłogę.\n *   - Kabel z drona (ok. 1 m) wpięty w płytkę stykową:\n *     czerwony = 3V3, czarny = GND, żółty = SDA -> pin 6,\n *     niebieski = SCL -> pin 7.\n *   - Biblioteka „VL53L1X” od Pololu (Menedżer bibliotek).\n *\n *  JAK TO DZIAŁA\n *   Czujnik wysyła błysk niewidzialnego światła i mierzy,\n *   po jakim czasie światło wróci. Jak echo w górach –\n *   tylko światło jest prawie milion razy szybsze od dźwięku!\n *\n *    [laser] ----błysk---->  |\n *            <---odbicie---  |  podłoga / dłoń\n *            |<-- odległość ->|\n *\n *   odległość = prędkość światła × czas / 2   (tam i z powrotem)\n *   Światło pokonuje 1 mm w ok. 3 bilionowe części sekundy (3 ps)!\n *\n *   Tryb Short: do ok. 1,3 m, mniej czuły na słońce.\n *   Budżet czasu 33 ms: tyle trwa jeden pomiar (ok. 30 na sekundę).\n *   STATUS 0 = dobry pomiar. Inna liczba = coś nie tak\n *   (za blisko, za daleko, za słabe odbicie).\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Zmierz odległość do dłoni. Zapisz ją w DLON_MM.\n *   2. Zbliżaj dłoń powoli. Znajdź najmniejszą odległość, przy której\n *      status jest jeszcze 0. Zapisz ją w NAJBLIZEJ_MM.\n *   3. Porównaj jasną i ciemną kartkę: wypisz siłę sygnału.\n */\n\n#include <Wire.h>\n#include <VL53L1X.h>\n\n// ================== KONFIGURACJA ==================\nconst int PIN_SDA = 6;\nconst int PIN_SCL = 7;\n\n// ZADANIE 1: wpisz odległość do dłoni [mm]. Pojawi się na wykresie.\nconst int DLON_MM = 0;\n// ZADANIE 2: wpisz najmniejszą odległość, przy której status = 0.\nconst int NAJBLIZEJ_MM = 0;\n// ==================================================\n\nVL53L1X laser;   // nasz czujnik\n\n// Uruchamia laser. Zwraca false, gdy się nie udało.\nbool laserStart() {\n  Wire.begin(PIN_SDA, PIN_SCL);\n  Wire.setClock(100000);   // 100 kHz: kabel I2C ma ok. 1 m, więc wolniej i pewniej\n  Wire.setTimeOut(50);     // nie czekaj w nieskończoność, gdy czujnik milczy\n  laser.setTimeout(500);\n  if (!laser.init()) return false;\n  laser.setDistanceMode(VL53L1X::Short);     // tryb krótki\n  laser.setMeasurementTimingBudget(33000);   // 33 ms (w mikrosekundach)\n  laser.startContinuous(33);                 // mierz bez przerwy\n  return true;\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(1000);\n  while (!laserStart()) {\n    Serial.println(\"Nie widzę lasera! Uruchom skaner L02. Widzi 0x29? To może być inny model czujnika – zawołaj prowadzącego.\");\n    delay(2000);\n  }\n  Serial.println(\"L03: laser działa.\");\n}\n\nvoid loop() {\n  if (laser.dataReady()) {           // nowy pomiar gotowy?\n    laser.read(false);               // odczytaj go (bez czekania)\n    Serial.print(\"odleglosc_mm:\");\n    Serial.print(laser.ranging_data.range_mm);\n    Serial.print(\",status:\");\n    Serial.print(laser.ranging_data.range_status);\n    Serial.print(\",dlon:\");\n    Serial.print(DLON_MM);\n    Serial.print(\",najblizej:\");\n    Serial.print(NAJBLIZEJ_MM);\n    // ZADANIE 3: usuń // z dwóch linii niżej. Pokażą siłę odbitego\n    // światła. Porównaj jasną i ciemną kartkę.\n    // Serial.print(\",sygnal:\");\n    // Serial.print(laser.ranging_data.peak_signal_count_rate_MCPS);\n    Serial.println();\n  }\n}\n",
 "uczen/L04_akcelerometr": "/*\n * ==============================================================\n *  LEKCJA 04: AKCELEROMETR MPU6050 – BEZ BIBLIOTEKI\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 2\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Co to są REJESTRY czujnika.\n *   - Jak czytać i zapisywać rejestry przez I2C (biblioteka Wire).\n *   - Co mierzy akcelerometr, a co żyroskop.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - MPU6050 na dronie, płasko, strzałka osi X do przodu.\n *   - Kabel z drona (ok. 1 m) wpięty w płytkę stykową:\n *     czerwony = 3V3, czarny = GND, żółty = SDA -> pin 6,\n *     niebieski = SCL -> pin 7.\n *\n *  JAK TO DZIAŁA\n *   Czujnik ma w środku ponumerowane SZUFLADKI (rejestry).\n *   W każdej leży jedna liczba 0..255 (jeden bajt).\n *\n *     szufladka 0x75: „kim jestem” (WHO_AM_I), zwykle 0x68\n *     szufladka 0x6B: zasilanie – wpisz 0, żeby obudzić czujnik\n *     szufladki 0x3B..0x48: pomiary (14 bajtów):\n *\n *      0x3B 0x3C | 0x3D 0x3E | 0x3F 0x40 | 0x41 0x42 | 0x43 ... 0x48\n *        acc X   |   acc Y   |   acc Z   |   temp.   |  gyro X, Y, Z\n *\n *   Każdy pomiar zajmuje 2 szufladki: starszy i młodszy bajt.\n *   Sklejamy je: liczba = starszy * 256 + młodszy.\n *\n *   AKCELEROMETR mierzy przyspieszenie w „g”. Gdy dron stoi,\n *   czuje tylko grawitację: oś Z pokazuje około 1 g.\n *   ŻYROSKOP mierzy, jak szybko się obracasz (stopnie na sekundę).\n *   Gdy dron stoi, pokazuje około 0.\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Przelicz surowe liczby na g i °/s.\n *   2. Przechyl drona i obserwuj osie na Plotterze.\n *   3. Policz kąt przechylenia z akcelerometru.\n */\n\n#include <Wire.h>\n\n// ================== KONFIGURACJA ==================\nconst int PIN_SDA = 6;\nconst int PIN_SCL = 7;\nconst int MPU = 0x68;                // adres czujnika na I2C\nconst float LSB_NA_G = 16384.0;      // zakres ±2 g:     16384 = 1 g\nconst float LSB_NA_STOPIEN = 131.0;  // zakres ±250 °/s: 131 = 1 °/s\n// ==================================================\n\n// Zapisuje liczbę do szufladki (rejestru) czujnika.\nvoid zapiszRejestr(byte rejestr, byte wartosc) {\n  Wire.beginTransmission(MPU);\n  Wire.write(rejestr);      // numer szufladki\n  Wire.write(wartosc);      // co do niej wkładamy\n  Wire.endTransmission();\n}\n\n// Czyta jedną szufladkę.\nbyte czytajRejestr(byte rejestr) {\n  Wire.beginTransmission(MPU);\n  Wire.write(rejestr);\n  Wire.endTransmission(false);   // false = nie kończ rozmowy\n  Wire.requestFrom(MPU, 1);\n  return Wire.read();\n}\n\n// Skleja dwa bajty w jedną liczbę ze znakiem (może być ujemna).\nint16_t sklej(byte starszy, byte mlodszy) {\n  return (int16_t)((starszy << 8) | mlodszy);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(1000);\n  Wire.begin(PIN_SDA, PIN_SCL);\n  Wire.setClock(100000);   // 100 kHz: kabel I2C ma ok. 1 m, więc wolniej i pewniej\n  Wire.setTimeOut(50);     // nie czekaj w nieskończoność, gdy czujnik milczy\n\n  byte kto = czytajRejestr(0x75);   // WHO_AM_I\n  Serial.print(\"WHO_AM_I = 0x\");\n  Serial.println(kto, HEX);\n  if (kto != 0x68) {\n    // Klony czujnika często mają inną wartość. Nie blokujemy programu.\n    Serial.println(\"Uwaga: oczekiwałem 0x68. To może być klon. Próbuję dalej.\");\n  }\n\n  zapiszRejestr(0x6B, 0);   // budzimy czujnik (po włączeniu śpi)\n  delay(100);\n}\n\nvoid loop() {\n  // Czytamy 14 szufladek naraz, zaczynając od 0x3B.\n  Wire.beginTransmission(MPU);\n  Wire.write(0x3B);\n  Wire.endTransmission(false);\n  Wire.requestFrom(MPU, 14);\n  byte b[14];\n  for (int i = 0; i < 14; i++) b[i] = Wire.read();\n\n  // ZADANIE 1: teraz to surowe liczby (np. 16384 zamiast 1 g).\n  // Podziel ax, ay, az przez LSB_NA_G, a gx, gy, gz przez LSB_NA_STOPIEN.\n  // Przykład:  float ax = sklej(b[0], b[1]) / LSB_NA_G;\n  float ax = sklej(b[0], b[1]);\n  float ay = sklej(b[2], b[3]);\n  float az = sklej(b[4], b[5]);\n  float gx = sklej(b[8], b[9]);\n  float gy = sklej(b[10], b[11]);\n  float gz = sklej(b[12], b[13]);\n\n  // ZADANIE 3: policz kąt przechylenia z akcelerometru.\n  // Podpowiedź: atan2(ay, az) daje kąt w radianach.\n  // Pomnóż go przez 180.0 / PI, żeby dostać stopnie.\n  float kat = 0;\n\n  // Kliknij nazwę w legendzie Plottera, żeby ukryć/pokazać linię.\n  Serial.print(\"ax_g:\");   Serial.print(ax);\n  Serial.print(\",ay_g:\");  Serial.print(ay);\n  Serial.print(\",az_g:\");  Serial.print(az);\n  Serial.print(\",gx:\");    Serial.print(gx);\n  Serial.print(\",gy:\");    Serial.print(gy);\n  Serial.print(\",gz:\");    Serial.print(gz);\n  Serial.print(\",kat:\");   Serial.println(kat);\n  delay(20);   // 50 pomiarów na sekundę\n}\n",
 "uczen/L05_pwm_dioda": "/*\n * ==============================================================\n *  LEKCJA 05: PWM – JAK „ŚCISZYĆ” DIODĘ\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 3\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Co to jest PWM i wypełnienie.\n *   - Dlaczego szybkie mruganie oko widzi jako słabsze światło.\n *   - Jak zrobić PWM sprzętem (moduł LEDC w ESP32).\n *   - Jak oglądać dane na wykresie (Serial Plotter).\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Kabel USB. Dioda RGB jest na płytce.\n *   - (opcjonalnie) zewnętrzna dioda: pin LED_ZEW -> rezystor 220 Ω\n *     -> dłuższa nóżka diody, krótsza nóżka -> GND.\n *\n *  JAK TO DZIAŁA\n *   Pin umie tylko dwie rzeczy: włączony (1) albo wyłączony (0).\n *   Żeby dioda świeciła „w połowie”, szybko ją włączamy i wyłączamy.\n *   WYPEŁNIENIE mówi, przez jaką część czasu jest włączona.\n *   Analogia: wentylator, który włączasz na chwilę co chwilę –\n *   im dłużej włączony, tym mocniej dmucha „średnio”.\n *\n *    25%:  _       _       _\n *         | |_____| |_____| |_____\n *    50%:  ___     ___     ___\n *         |   |___|   |___|   |___\n *    75%:  _____   _____   _____\n *         |     |_|     |_|     |_\n *         |<----->|\n *           okres\n *\n *   Program ma 3 części:\n *    1) PWM „ręcznie” i bardzo wolno (okres 2 s) – widać włącz/wyłącz,\n *       a na Plotterze prostokąt 0/1.\n *    2) Okres coraz krótszy – aż oko widzi tylko jasność.\n *    3) PWM sprzętowy (LEDC) – płytka mruga sama, 5000 razy na sekundę.\n *   Otwórz: Narzędzia -> Serial Plotter.\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Zmień WYPELNIENIE (np. 10, 50, 90) i obserwuj wykres.\n *   2. Zmień okres najwolniejszego etapu.\n *   3. Zrób „oddychającą” diodę: jasność płynnie rośnie i maleje.\n */\n\n// ================== KONFIGURACJA ==================\n#ifdef RGB_BUILTIN\nconst int PIN_DIODY = RGB_BUILTIN;   // kolorowa dioda na płytce\n#else\nconst int PIN_DIODY = LED_BUILTIN;\n#endif\nconst int LED_ZEW = 22;          // zewnętrzna dioda (opcjonalna), wolny pin\nconst int JASNOSC_RGB = 40;      // 0..255, dioda RGB jest bardzo jasna!\n\n// ZADANIE 1: wypełnienie w procentach (0..100). Spróbuj 10, 50, 90.\nconst int WYPELNIENIE = 50;\n\n// ZADANIE 2: okresy kolejnych etapów w milisekundach.\n// Zmień pierwszy (najwolniejszy) etap, np. na 4000.\nconst int OKRESY_MS[] = {2000, 1000, 500, 200, 100, 50, 20, 10, 5};\nconst int ILE_ETAPOW = 9;\n\nconst int LEDC_HZ = 5000;        // PWM sprzętowy: 5000 okresów na sekundę\nconst int LEDC_BITY = 8;         // 8 bitów = liczby 0..255\n// ==================================================\n\nbool stan_diody = false;\n\n// Włącza albo wyłącza obie diody naraz.\nvoid ustawDiode(bool wlaczona) {\n  if (wlaczona == stan_diody) return;   // nic się nie zmienia\n  stan_diody = wlaczona;\n  digitalWrite(LED_ZEW, wlaczona ? HIGH : LOW);\n#ifdef RGB_BUILTIN\n  int j = wlaczona ? JASNOSC_RGB : 0;\n  rgbLedWrite(PIN_DIODY, j, j, j);\n#else\n  digitalWrite(PIN_DIODY, wlaczona ? HIGH : LOW);\n#endif\n}\n\n// Jeden etap ręcznego PWM. micros() to zegar w mikrosekundach.\n// Reszta z dzielenia (%) mówi, w którym miejscu okresu jesteśmy.\nvoid etapReczny(long okres_ms, long czas_etapu_ms) {\n  long okres_us = okres_ms * 1000;\n  long wlaczona_us = okres_us * WYPELNIENIE / 100;\n  unsigned long start = millis();\n  unsigned long ostatni_wykres = 0;\n  while (millis() - start < czas_etapu_ms) {\n    long miejsce = micros() % okres_us;\n    ustawDiode(miejsce < wlaczona_us);\n    if (millis() - ostatni_wykres >= 20) {   // punkt wykresu co 20 ms\n      ostatni_wykres = millis();\n      Serial.print(\"stan:\");\n      Serial.print(stan_diody ? 1 : 0);\n      Serial.print(\",srednia:\");\n      Serial.println(WYPELNIENIE / 100.0);\n    }\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(1000);\n  pinMode(LED_ZEW, OUTPUT);\n  pinMode(PIN_DIODY, OUTPUT);\n  ustawDiode(true);\n  ustawDiode(false);\n\n  // Części 1 i 2: PWM ręcznie, coraz szybciej\n  for (int i = 0; i < ILE_ETAPOW; i++) {\n    long czas = max(2L * OKRESY_MS[i], 4000L);   // co najmniej 4 s\n    etapReczny(OKRESY_MS[i], czas);\n  }\n  ustawDiode(false);\n\n  // Część 3: PWM sprzętowy. LEDC sam mruga pinem, a procesor jest wolny.\n  ledcAttach(LED_ZEW, LEDC_HZ, LEDC_BITY);\n}\n\n// Ustawia jasność 0..100% na obu diodach.\n// Dioda RGB ma w środku własny mały sterownik PWM.\nvoid jasnosc(int procent) {\n  ledcWrite(LED_ZEW, procent * 255 / 100);\n#ifdef RGB_BUILTIN\n  int j = procent * JASNOSC_RGB / 100;\n  rgbLedWrite(PIN_DIODY, j, j, j);\n#endif\n  Serial.print(\"jasnosc:\");\n  Serial.println(procent);\n}\n\nvoid loop() {\n  // ZADANIE 3: „oddychająca” dioda.\n  // Teraz jasność stoi w miejscu. Zrób dwie pętle for:\n  // jedną od 0 do 100, drugą od 100 do 0, z delay(15) w środku.\n  jasnosc(WYPELNIENIE);\n  delay(15);\n}\n",
 "uczen/L06_jeden_silnik": "/*\n * ==============================================================\n *  LEKCJA 06: JEDEN SILNIK\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 3\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Jak PWM steruje mocą silnika.\n *   - Jak wysyłać komendy z Serial Monitora do płytki.\n *   - Po co jest RAMPA (moc rośnie powoli) i limit MAX_MOC.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Dron na prowadnicy, zasilanie z kabla, USB do komputera.\n *   - Silnik M1 na pinie 18 (przez moduł ESC).\n *\n *  JAK TO DZIAŁA\n *   Silnik to „duża dioda”: im większe wypełnienie PWM,\n *   tym szybciej się kręci. Moduł ESC (w środku tranzystor MOSFET)\n *   to szybki włącznik, który przełącza duży prąd silnika.\n *\n *   ESP32 --PWM--> [ESC] ==prąd==> (M1)\n *\n *   RAMPA: jak pedał gazu w samochodzie – wciskasz powoli,\n *   a nie od razu do podłogi. Na wykresie widać „schodek”\n *   zamieniony na pochylnię:\n *\n *    zadana:  ______          moc:      ______\n *            |                         /\n *       _____|               _______ /\n *\n *  BEZPIECZEŃSTWO\n *   - Silniki startują ROZBROJONE (dioda czerwona).\n *   - \"u\" + Enter = uzbrój (dioda zielona).\n *   - \"x\" albo spacja = STOP. Przycisk BOOT na płytce = STOP.\n *   - Program nigdy nie da więcej niż MAX_MOC.\n *\n *  KOMENDY (Serial Monitor, 115200, „Nowa linia”)\n *   u      – uzbrój\n *   x      – STOP\n *   0..100 – moc silnika M1 w procentach, np. 25\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Znajdź moc, przy której śmigło rusza. Zapisz ją w MOC_STARTU.\n *   2. Ustaw PWM_HZ = 200 i posłuchaj silnika. Potem wróć do 20000.\n *   3. Zmień RAMPA i zobacz na Plotterze, jak zmienia się pochylnia.\n */\n\n// ================== KONFIGURACJA ==================\n#define TRYB_MOSFET          // moduły ESC sterowane PWM 20 kHz (domyślnie)\n// #define TRYB_ESC_RC       // albo regulatory ESC (impulsy 1000-2000 us)\n                             // Zostaw odkomentowany TYLKO JEDEN tryb!\n\nconst int PINY_SILNIKOW[4] = {18, 19, 20, 21};   // M1, M2, M3, M4\nconst int PIN_STOP = 9;          // przycisk BOOT = STOP awaryjny\nconst float MAX_MOC = 60;        // [%] tej mocy program nigdy nie przekroczy\n\n// ZADANIE 3: jak szybko może rosnąć moc [% na sekundę].\n// Spróbuj 5, potem 40. Obserwuj na Plotterze linie zadana i moc.\nconst float RAMPA = 20;\n\n// ZADANIE 2: zmień 20000 na 200, wgraj i posłuchaj silnika.\n// Potem KONIECZNIE wróć do 20000.\nconst int PWM_HZ = 20000;        // TRYB_MOSFET: częstotliwość PWM\nconst int PWM_BITY = 10;         // 10 bitów = liczby 0..1023\nconst int ESC_HZ = 50;           // TRYB_ESC_RC: 50 impulsów na sekundę\nconst int ESC_BITY = 14;\n\n// ZADANIE 1: wpisuj moc 5, 6, 7... aż śmigło ruszy.\n// Wpisz tu tę moc [%]. Na Plotterze pojawi się jako linia „start”.\nconst int MOC_STARTU = 0;\n// ==================================================\n\n#if defined(TRYB_MOSFET) && defined(TRYB_ESC_RC)\n#error \"Wybierz tylko jeden tryb: TRYB_MOSFET albo TRYB_ESC_RC\"\n#endif\n\n// ================== SILNIKI I BEZPIECZEŃSTWO ==================\n// Ta część jest taka sama we wszystkich lekcjach z silnikami.\n\nbool uzbrojony = false;                 // false = silniki zablokowane\nfloat moc_zadana[4] = {0, 0, 0, 0};     // [%] do tej mocy dążymy\nfloat moc_teraz[4] = {0, 0, 0, 0};      // [%] tyle jest teraz (po rampie)\nunsigned long czas_rampy = 0;\n\n// Dioda: czerwona = rozbrojony, zielona = uzbrojony.\nvoid pokazStan() {\n#ifdef RGB_BUILTIN\n  if (uzbrojony) rgbLedWrite(RGB_BUILTIN, 0, 30, 0);\n  else rgbLedWrite(RGB_BUILTIN, 30, 0, 0);\n#else\n  pinMode(LED_BUILTIN, OUTPUT);\n  digitalWrite(LED_BUILTIN, uzbrojony ? HIGH : LOW);\n#endif\n}\n\n// Pierwsza rzecz w setup(): wszystkie piny silników na 0.\nvoid silnikiNaZero() {\n  for (int i = 0; i < 4; i++) {\n    pinMode(PINY_SILNIKOW[i], OUTPUT);\n    digitalWrite(PINY_SILNIKOW[i], LOW);\n  }\n}\n\n// Wysyła moc [%] na silnik nr 0..3 (to M1..M4).\nvoid wyslijMoc(int nr, float moc) {\n  if (!uzbrojony) moc = 0;\n  moc = constrain(moc, 0, MAX_MOC);\n#ifdef TRYB_ESC_RC\n  float impuls_us = 1000 + moc * 10;    // 0% = 1000 us, 100% = 2000 us\n  uint32_t wypelnienie = impuls_us * ESC_HZ * (1 << ESC_BITY) / 1000000.0;\n#else\n  uint32_t wypelnienie = moc / 100.0 * ((1 << PWM_BITY) - 1);\n#endif\n  ledcWrite(PINY_SILNIKOW[nr], wypelnienie);\n}\n\n// Włącza PWM sprzętowy (LEDC) na pinach silników, z mocą 0.\nvoid silnikiStart() {\n  for (int i = 0; i < 4; i++) {\n#ifdef TRYB_ESC_RC\n    ledcAttach(PINY_SILNIKOW[i], ESC_HZ, ESC_BITY);\n#else\n    ledcAttach(PINY_SILNIKOW[i], PWM_HZ, PWM_BITY);\n#endif\n    wyslijMoc(i, 0);\n  }\n  pinMode(PIN_STOP, INPUT_PULLUP);\n  czas_rampy = millis();\n  pokazStan();\n}\n\n// RAMPA: moc zmienia się najwyżej o RAMPA % na sekundę.\nvoid rampa() {\n  float dt = (millis() - czas_rampy) / 1000.0;\n  czas_rampy = millis();\n  float krok = RAMPA * dt;\n  for (int i = 0; i < 4; i++) {\n    float cel = uzbrojony ? constrain(moc_zadana[i], 0, MAX_MOC) : 0;\n    if (moc_teraz[i] < cel) moc_teraz[i] = min(moc_teraz[i] + krok, cel);\n    else moc_teraz[i] = max(moc_teraz[i] - krok, cel);\n    wyslijMoc(i, moc_teraz[i]);\n  }\n}\n\nvoid ustawWszystkie(float moc) {\n  for (int i = 0; i < 4; i++) moc_zadana[i] = constrain(moc, 0, MAX_MOC);\n}\n\nvoid uzbroj() {\n  uzbrojony = true;\n  Serial.println(\"UZBROJONY! Uwaga na śmigła.\");\n  pokazStan();\n}\n\n// STOP: od razu wyłącza wszystkie silniki i mówi dlaczego.\nvoid stop(String powod) {\n  uzbrojony = false;\n  for (int i = 0; i < 4; i++) {\n    moc_zadana[i] = 0;\n    moc_teraz[i] = 0;\n    wyslijMoc(i, 0);\n  }\n  Serial.println(\"STOP! Powód: \" + powod);\n  pokazStan();\n}\n\nvoid sprawdzPrzycisk() {\n  if (uzbrojony && digitalRead(PIN_STOP) == LOW) stop(\"przycisk BOOT\");\n}\n\n// ================== KOMENDY Z SERIAL MONITORA ==================\n// Ta sama funkcja we wszystkich lekcjach. Czyta linię, np. \"p 0.05\":\n// litera trafia do komenda, liczba do komenda_liczba.\n// Sama liczba (np. \"40\") to komenda 'm'. \"x\" i spacja działają od razu.\nchar komenda = 0;\nfloat komenda_liczba = 0;\nString linia = \"\";\n\nbool czytajKomende() {\n  while (Serial.available() > 0) {\n    char znak = Serial.read();\n    if (linia.length() == 0 && (znak == 'x' || znak == 'X' || znak == ' ')) {\n      komenda = 'x';\n      return true;\n    }\n    if (znak == '\\n' || znak == '\\r') {\n      if (linia.length() == 0) continue;\n      komenda = linia.charAt(0);\n      if (isDigit(komenda)) {\n        komenda = 'm';\n        komenda_liczba = linia.toFloat();\n      } else {\n        komenda_liczba = linia.substring(1).toFloat();\n      }\n      linia = \"\";\n      return true;\n    }\n    linia += znak;\n  }\n  return false;\n}\n\n// ================== PROGRAM LEKCJI ==================\nunsigned long czas_wykresu = 0;\n\nvoid obsluzKomende() {\n  if (komenda == 'x') {\n    stop(\"komenda x\");\n  } else if (komenda == 'u') {\n    uzbroj();\n  } else if (komenda == 'm') {\n    if (!uzbrojony) {\n      Serial.println(\"Najpierw uzbrój: wpisz u\");\n      return;\n    }\n    moc_zadana[0] = constrain(komenda_liczba, 0, MAX_MOC);\n    Serial.print(\"Nowa moc M1 [%]: \");\n    Serial.println(moc_zadana[0]);\n  } else {\n    Serial.println(\"Znam komendy: u, x, liczba 0-100\");\n  }\n}\n\nvoid setup() {\n  silnikiNaZero();           // NAJPIERW silniki na 0!\n  Serial.begin(115200);\n  delay(1000);\n  silnikiStart();\n  Serial.println(\"L06: jeden silnik. Wpisz u, potem moc, np. 20.\");\n}\n\nvoid loop() {\n  if (czytajKomende()) obsluzKomende();\n  sprawdzPrzycisk();\n  rampa();\n\n  if (millis() - czas_wykresu >= 50) {   // wykres 20 razy na sekundę\n    czas_wykresu = millis();\n    Serial.print(\"zadana:\");\n    Serial.print(moc_zadana[0]);\n    Serial.print(\",moc:\");\n    Serial.print(moc_teraz[0]);\n    Serial.print(\",start:\");\n    Serial.println(MOC_STARTU);\n  }\n}\n",
 "uczen/L07_cztery_silniki": "/*\n * ==============================================================\n *  LEKCJA 07: CZTERY SILNIKI\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 3\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Co to jest TABLICA: jedna nazwa, kilka szufladek z numerami.\n *   - Jak pętla for robi to samo dla każdego silnika.\n *   - Jak sprawdzić, czy silniki są dobrze podłączone.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Dron na prowadnicy, zasilanie z kabla, USB do komputera.\n *   - Silniki M1..M4 na pinach 18, 19, 20, 21.\n *\n *  JAK TO DZIAŁA\n *   Tablica PINY_SILNIKOW to 4 szufladki. Numeracja od ZERA:\n *     PINY_SILNIKOW[0] = 18  (M1)\n *     PINY_SILNIKOW[1] = 19  (M2) ...\n *   Pętla for (int i = 0; i < 4; i++) { ... } robi coś\n *   dla i = 0, 1, 2, 3 – czyli dla każdego silnika.\n *\n *   Widok drona z góry:            CW  = jak wskazówki zegara\n *            PRZÓD                 CCW = przeciwnie do zegara\n *      M1 (CW)     M2 (CCW)\n *          \\       /\n *           [ ESP ]\n *          /       \\\n *      M4 (CCW)    M3 (CW)\n *   Silniki po przekątnej kręcą się w tę samą stronę.\n *   Dzięki temu dron nie obraca się wokół własnej osi.\n *   Zły kierunek? Zamień miejscami dwa kable tego silnika.\n *\n *  BEZPIECZEŃSTWO\n *   - Start ROZBROJONY (czerwona). \"u\" = uzbrój (zielona).\n *   - \"x\" albo spacja = STOP. Przycisk BOOT = STOP.\n *   - Program nigdy nie da więcej niż MAX_MOC.\n *\n *  KOMENDY\n *   u – uzbrój        x – STOP\n *   t – test kolejności silników\n *   r – rozpędzanie i zwalnianie wszystkich\n *   s – schody\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Zmień czas rozpędzania (CZAS_ROZPEDZANIA_MS).\n *   2. Zrób „schody”: moc 10, 20, 30, 40%, każda przez 1,5 s.\n */\n\n// ================== KONFIGURACJA ==================\n#define TRYB_MOSFET          // moduły ESC sterowane PWM 20 kHz (domyślnie)\n// #define TRYB_ESC_RC       // albo regulatory ESC (impulsy 1000-2000 us)\n                             // Zostaw odkomentowany TYLKO JEDEN tryb!\n\nconst int PINY_SILNIKOW[4] = {18, 19, 20, 21};   // M1, M2, M3, M4\nconst int PIN_STOP = 9;          // przycisk BOOT = STOP awaryjny\nconst float MAX_MOC = 60;        // [%] tej mocy program nigdy nie przekroczy\nconst float RAMPA = 30;          // [% na sekundę] najszybsza zmiana mocy\n\nconst int PWM_HZ = 20000;        // TRYB_MOSFET: częstotliwość PWM\nconst int PWM_BITY = 10;         // 10 bitów = liczby 0..1023\nconst int ESC_HZ = 50;           // TRYB_ESC_RC: 50 impulsów na sekundę\nconst int ESC_BITY = 14;\n\nconst float MOC_TESTU = 15;      // [%] niska moc do testu kolejności\nconst float MOC_POKAZU = 40;     // [%] najwyższa moc przy rozpędzaniu\n\n// ZADANIE 1: czas rozpędzania w ms. Spróbuj 1000 i 8000.\n// Przy 1000 RAMPA nie pozwoli rozpędzić się tak szybko – sprawdź na Plotterze!\nconst int CZAS_ROZPEDZANIA_MS = 3000;\n\nconst String GDZIE[4] = {\"przód-lewy\", \"przód-prawy\", \"tył-prawy\", \"tył-lewy\"};\nconst String KIERUNEK[4] = {\"CW (jak zegar)\", \"CCW (przeciwnie do zegara)\",\n                            \"CW (jak zegar)\", \"CCW (przeciwnie do zegara)\"};\n// ==================================================\n\n#if defined(TRYB_MOSFET) && defined(TRYB_ESC_RC)\n#error \"Wybierz tylko jeden tryb: TRYB_MOSFET albo TRYB_ESC_RC\"\n#endif\n\n// ================== SILNIKI I BEZPIECZEŃSTWO ==================\n// Ta część jest taka sama we wszystkich lekcjach z silnikami.\n\nbool uzbrojony = false;                 // false = silniki zablokowane\nfloat moc_zadana[4] = {0, 0, 0, 0};     // [%] do tej mocy dążymy\nfloat moc_teraz[4] = {0, 0, 0, 0};      // [%] tyle jest teraz (po rampie)\nunsigned long czas_rampy = 0;\n\n// Dioda: czerwona = rozbrojony, zielona = uzbrojony.\nvoid pokazStan() {\n#ifdef RGB_BUILTIN\n  if (uzbrojony) rgbLedWrite(RGB_BUILTIN, 0, 30, 0);\n  else rgbLedWrite(RGB_BUILTIN, 30, 0, 0);\n#else\n  pinMode(LED_BUILTIN, OUTPUT);\n  digitalWrite(LED_BUILTIN, uzbrojony ? HIGH : LOW);\n#endif\n}\n\n// Pierwsza rzecz w setup(): wszystkie piny silników na 0.\nvoid silnikiNaZero() {\n  for (int i = 0; i < 4; i++) {\n    pinMode(PINY_SILNIKOW[i], OUTPUT);\n    digitalWrite(PINY_SILNIKOW[i], LOW);\n  }\n}\n\n// Wysyła moc [%] na silnik nr 0..3 (to M1..M4).\nvoid wyslijMoc(int nr, float moc) {\n  if (!uzbrojony) moc = 0;\n  moc = constrain(moc, 0, MAX_MOC);\n#ifdef TRYB_ESC_RC\n  float impuls_us = 1000 + moc * 10;    // 0% = 1000 us, 100% = 2000 us\n  uint32_t wypelnienie = impuls_us * ESC_HZ * (1 << ESC_BITY) / 1000000.0;\n#else\n  uint32_t wypelnienie = moc / 100.0 * ((1 << PWM_BITY) - 1);\n#endif\n  ledcWrite(PINY_SILNIKOW[nr], wypelnienie);\n}\n\n// Włącza PWM sprzętowy (LEDC) na pinach silników, z mocą 0.\nvoid silnikiStart() {\n  for (int i = 0; i < 4; i++) {\n#ifdef TRYB_ESC_RC\n    ledcAttach(PINY_SILNIKOW[i], ESC_HZ, ESC_BITY);\n#else\n    ledcAttach(PINY_SILNIKOW[i], PWM_HZ, PWM_BITY);\n#endif\n    wyslijMoc(i, 0);\n  }\n  pinMode(PIN_STOP, INPUT_PULLUP);\n  czas_rampy = millis();\n  pokazStan();\n}\n\n// RAMPA: moc zmienia się najwyżej o RAMPA % na sekundę.\nvoid rampa() {\n  float dt = (millis() - czas_rampy) / 1000.0;\n  czas_rampy = millis();\n  float krok = RAMPA * dt;\n  for (int i = 0; i < 4; i++) {\n    float cel = uzbrojony ? constrain(moc_zadana[i], 0, MAX_MOC) : 0;\n    if (moc_teraz[i] < cel) moc_teraz[i] = min(moc_teraz[i] + krok, cel);\n    else moc_teraz[i] = max(moc_teraz[i] - krok, cel);\n    wyslijMoc(i, moc_teraz[i]);\n  }\n}\n\nvoid ustawWszystkie(float moc) {\n  for (int i = 0; i < 4; i++) moc_zadana[i] = constrain(moc, 0, MAX_MOC);\n}\n\nvoid uzbroj() {\n  uzbrojony = true;\n  Serial.println(\"UZBROJONY! Uwaga na śmigła.\");\n  pokazStan();\n}\n\n// STOP: od razu wyłącza wszystkie silniki i mówi dlaczego.\nvoid stop(String powod) {\n  uzbrojony = false;\n  for (int i = 0; i < 4; i++) {\n    moc_zadana[i] = 0;\n    moc_teraz[i] = 0;\n    wyslijMoc(i, 0);\n  }\n  Serial.println(\"STOP! Powód: \" + powod);\n  pokazStan();\n}\n\nvoid sprawdzPrzycisk() {\n  if (uzbrojony && digitalRead(PIN_STOP) == LOW) stop(\"przycisk BOOT\");\n}\n\n// ================== KOMENDY Z SERIAL MONITORA ==================\n// Ta sama funkcja we wszystkich lekcjach. Czyta linię, np. \"p 0.05\":\n// litera trafia do komenda, liczba do komenda_liczba.\n// Sama liczba (np. \"40\") to komenda 'm'. \"x\" i spacja działają od razu.\nchar komenda = 0;\nfloat komenda_liczba = 0;\nString linia = \"\";\n\nbool czytajKomende() {\n  while (Serial.available() > 0) {\n    char znak = Serial.read();\n    if (linia.length() == 0 && (znak == 'x' || znak == 'X' || znak == ' ')) {\n      komenda = 'x';\n      return true;\n    }\n    if (znak == '\\n' || znak == '\\r') {\n      if (linia.length() == 0) continue;\n      komenda = linia.charAt(0);\n      if (isDigit(komenda)) {\n        komenda = 'm';\n        komenda_liczba = linia.toFloat();\n      } else {\n        komenda_liczba = linia.substring(1).toFloat();\n      }\n      linia = \"\";\n      return true;\n    }\n    linia += znak;\n  }\n  return false;\n}\n\n// ================== PROGRAM LEKCJI ==================\nchar do_zrobienia = 0;           // co mamy zaraz zrobić: 't', 'r' albo 's'\nunsigned long czas_wykresu = 0;\n\nvoid obsluzKomende() {\n  if (komenda == 'x') {\n    stop(\"komenda x\");\n  } else if (komenda == 'u') {\n    uzbroj();\n  } else if (komenda == 't' || komenda == 'r' || komenda == 's') {\n    if (uzbrojony) do_zrobienia = komenda;\n    else Serial.println(\"Najpierw uzbrój: wpisz u\");\n  } else {\n    Serial.println(\"Znam komendy: u, x, t, r, s\");\n  }\n}\n\n// Pilnuje bezpieczeństwa i rysuje wykres. Wołamy ją cały czas.\nvoid pilnuj() {\n  if (czytajKomende()) obsluzKomende();\n  sprawdzPrzycisk();\n  rampa();\n  if (millis() - czas_wykresu >= 50) {\n    czas_wykresu = millis();\n    for (int i = 0; i < 4; i++) {\n      Serial.print(\"M\");\n      Serial.print(i + 1);\n      Serial.print(\":\");\n      Serial.print(moc_teraz[i]);\n      Serial.print(i < 3 ? \",\" : \"\\n\");\n    }\n  }\n}\n\n// Czeka ms milisekund, ale cały czas pilnuje bezpieczeństwa.\n// Zwraca false, gdy w tym czasie był STOP.\nbool czekaj(unsigned long ms) {\n  unsigned long start = millis();\n  while (millis() - start < ms) {\n    pilnuj();\n    if (!uzbrojony) return false;\n    delay(5);\n  }\n  return true;\n}\n\nvoid testKolejnosci() {\n  Serial.println(\"TEST KOLEJNOŚCI. Patrz, które śmigło się kręci!\");\n  for (int i = 0; i < 4; i++) {\n    Serial.println(\"M\" + String(i + 1) + \" (\" + GDZIE[i] + \") powinien kręcić się \" + KIERUNEK[i]);\n    moc_zadana[i] = MOC_TESTU;\n    bool dalej = czekaj(1000);\n    moc_zadana[i] = 0;\n    if (!dalej || !czekaj(800)) return;\n  }\n  Serial.println(\"Test skończony.\");\n}\n\nvoid rozpedzanie() {\n  Serial.println(\"ROZPĘDZANIE wszystkich silników.\");\n  int kroki = 50;\n  for (int k = 0; k <= kroki; k++) {\n    ustawWszystkie(MOC_POKAZU * k / kroki);\n    if (!czekaj(CZAS_ROZPEDZANIA_MS / kroki)) return;\n  }\n  if (!czekaj(1000)) return;\n  Serial.println(\"ZWALNIANIE.\");\n  for (int k = kroki; k >= 0; k--) {\n    ustawWszystkie(MOC_POKAZU * k / kroki);\n    if (!czekaj(CZAS_ROZPEDZANIA_MS / kroki)) return;\n  }\n}\n\n// ZADANIE 2: „schody” – moc 10, 20, 30, 40%, każda przez 1,5 s.\n// Użyj pętli for, funkcji ustawWszystkie(moc) i czekaj(ms).\n// Ważne: pisz  if (!czekaj(1500)) return;\n// – wtedy schody zatrzymają się po STOP.\nvoid schody() {\n  Serial.println(\"Schody jeszcze nie gotowe – to Twoje ZADANIE 2!\");\n}\n\nvoid setup() {\n  silnikiNaZero();           // NAJPIERW silniki na 0!\n  Serial.begin(115200);\n  delay(1000);\n  silnikiStart();\n  Serial.println(\"L07: cztery silniki. Wpisz u, potem t, r albo s.\");\n}\n\nvoid loop() {\n  pilnuj();\n  char co = do_zrobienia;\n  do_zrobienia = 0;\n  if (co == 't') testKolejnosci();\n  if (co == 'r') rozpedzanie();\n  if (co == 's') schody();\n  ustawWszystkie(0);         // po każdym pokazie wracamy do zera\n}\n",
 "uczen/L08_filtr": "/*\n * ==============================================================\n *  LEKCJA 08: FILTR – JAK WYGŁADZIĆ SKACZĄCY POMIAR\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 4\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Dlaczego pomiary „skaczą” (szum).\n *   - Średnia z N ostatnich pomiarów.\n *   - Filtr wykładniczy (z liczbą alfa).\n *   - Że gładszy wykres = większe opóźnienie.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Laser VL53L1X: 3,3 V, GND, SDA -> pin 6, SCL -> pin 7.\n *\n *  JAK TO DZIAŁA\n *   Na Plotterze są 3 linie z TEGO SAMEGO pomiaru:\n *    surowy      – prosto z czujnika, skacze,\n *    srednia     – średnia z N ostatnich pomiarów,\n *    wykladniczy – nowy = alfa × pomiar + (1 − alfa) × stary.\n *\n *   ŚREDNIA: jak ocena na koniec roku – liczysz kilka ostatnich\n *   ocen, więc jedna pała nie zmienia wszystkiego.\n *\n *   WYKŁADNICZY: jak plotka – każda nowa wiadomość trochę\n *   zmienia zdanie. alfa = 1: wierzysz tylko nowej (bez filtra).\n *   alfa = 0,1: zmieniasz zdanie powoli (mocny filtr).\n *\n *    surowy:   /\\/\\_/\\/\\__/\\/\\/\\\n *    filtr:    ~~~~~~~~~~~~~~~~~   gładko, ale ze spóźnieniem\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Zmień N (np. 2, 10, 20). Co się dzieje z linią srednia?\n *   2. Zmień ALFA (np. 0.8, 0.3, 0.05).\n *   3. Szybko ruszaj dłonią. Która linia spóźnia się najbardziej?\n */\n\n#include <Wire.h>\n#include <VL53L1X.h>\n\n// ================== KONFIGURACJA ==================\nconst int PIN_SDA = 6;\nconst int PIN_SCL = 7;\n\n// ZADANIE 1: z ilu ostatnich pomiarów liczymy średnią (1..20)\nconst int N = 5;\n// ZADANIE 2: siła filtra wykładniczego (0..1). Mniej = gładziej.\nconst float ALFA = 0.5;\nstatic_assert(N >= 1 && N <= 20, \"N musi być od 1 do 20\");\n// ==================================================\n\nVL53L1X laser;\n\nint ostatnie[20];      // tablica na ostatnie pomiary\nint gdzie = 0;         // do której szufladki wpisać następny\nfloat wykladniczy = 0;\nbool pierwszy = true;\n\nbool laserStart() {\n  Wire.begin(PIN_SDA, PIN_SCL);\n  Wire.setClock(100000);   // 100 kHz: kabel I2C ma ok. 1 m, więc wolniej i pewniej\n  Wire.setTimeOut(50);     // nie czekaj w nieskończoność, gdy czujnik milczy\n  laser.setTimeout(500);\n  if (!laser.init()) return false;\n  laser.setDistanceMode(VL53L1X::Short);\n  laser.setMeasurementTimingBudget(33000);\n  laser.startContinuous(33);\n  return true;\n}\n\n// Średnia z N ostatnich pomiarów.\nfloat srednia(int pomiar) {\n  ostatnie[gdzie] = pomiar;          // wkładamy nowy pomiar\n  gdzie = (gdzie + 1) % N;           // następna szufladka (w kółko)\n  long suma = 0;\n  for (int i = 0; i < N; i++) suma += ostatnie[i];\n  return suma / (float)N;\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  delay(1000);\n  while (!laserStart()) {\n    Serial.println(\"Nie widzę lasera! Uruchom skaner L02. Widzi 0x29? To może być inny model czujnika – zawołaj prowadzącego.\");\n    delay(2000);\n  }\n}\n\nvoid loop() {\n  if (laser.dataReady()) {\n    int surowy = laser.read(false);\n    if (pierwszy) {                  // na start: wszystko = pierwszy pomiar\n      for (int i = 0; i < 20; i++) ostatnie[i] = surowy;\n      wykladniczy = surowy;\n      pierwszy = false;\n    }\n\n    float sr = srednia(surowy);\n    // Filtr wykładniczy: trochę nowego pomiaru + dużo starej wartości\n    wykladniczy = ALFA * surowy + (1 - ALFA) * wykladniczy;\n\n    Serial.print(\"surowy:\");\n    Serial.print(surowy);\n    Serial.print(\",srednia:\");\n    Serial.print(sr);\n    Serial.print(\",wykladniczy:\");\n    Serial.println(wykladniczy);\n  }\n}\n",
 "uczen/L09_trzymaj_wysokosc": "/*\n * ==============================================================\n *  LEKCJA 09: TRZYMAJ WYSOKOŚĆ – REGULATOR PID\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 4\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Co to jest REGULATOR i SPRZĘŻENIE ZWROTNE.\n *   - Co robią liczby Kp, Ki i Kd.\n *   - Jak dobrać je krok po kroku, patrząc na wykres.\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Dron na prowadnicy, zasilanie z kabla, USB.\n *   - Silniki M1..M4 (piny 18..21), laser patrzy w dół (SDA 6, SCL 7).\n *\n *  JAK TO DZIAŁA\n *   Analogia: PRYSZNIC. Za zimno? Kręcisz kurkiem na ciepło.\n *   Im zimniej, tym mocniej kręcisz. Tak samo dron:\n *\n *     BŁĄD = wysokość zadana − wysokość zmierzona\n *     (dron za nisko -> błąd dodatni -> więcej mocy)\n *\n *     moc = moc_zawisu + Kp·błąd + Ki·suma_błędów + Kd·zmiana_błędu\n *\n *     Kp – „im dalej, tym mocniej”. Główny kurek.\n *     Ki – „ciągle za nisko? dodaję po trochu”. Usuwa stały błąd.\n *     Kd – „zbliżam się szybko? hamuję”. Gasi bujanie.\n *\n *      zadana ---> (+) --błąd--> [ PID ] --moc--> [silniki] --> dron\n *                   ^ (−)                                        |\n *                   +--------------- [laser] <---wysokość--------+\n *\n *   Regulator liczy nową moc przy każdym pomiarze lasera (co 33 ms).\n *   ANTI-WINDUP: suma błędów ma limit SUMA_MAX, żeby się nie „nakręcić”.\n *\n *  BEZPIECZEŃSTWO\n *   - Start ROZBROJONY (czerwona). \"u\" = uzbrój (zielona).\n *   - \"x\" albo spacja = STOP. Przycisk BOOT = STOP.\n *   - Automatyczny STOP: brak pomiaru > 200 ms, wysokość > WYSOKOSC_MAX,\n *     lot dłuższy niż CZAS_MAX. Powód pojawia się w Serial Monitorze.\n *   - \"h 0\" = lądowanie: silniki płynnie zwalniają do zera.\n *\n *  KOMENDY (Serial Monitor, 115200, „Nowa linia”)\n *   u – uzbrój        x – STOP         ? – pokaż nastawy\n *   h 300  – zadana wysokość w mm\n *   p 0.05 – Kp     i 0.002 – Ki     d 0.5 – Kd\n *   z 35   – moc zawisu w %\n *\n *  ZADANIA (szukaj w kodzie napisu ZADANIE)\n *   1. Ki = 0, Kd = 0. Zacznij od Kp = 0.02 i zwiększaj.\n *      Kiedy dron zaczyna się bujać? Wybierz trochę mniej.\n *   2. Dodaj Ki do wzoru. Ustaw np. „i 0.002”. Co się zmienia?\n *   3. Dodaj Kd do wzoru. Ustaw np. „d 0.5”. Co się zmienia?\n *   4. Opisz własnymi słowami, co robi Kp, Ki i Kd.\n *\n *  ZADANIE 4: wasze obserwacje\n *   Kp: ...\n *   Ki: ...\n *   Kd: ...\n */\n\n#include <Wire.h>\n#include <VL53L1X.h>\n\n// ================== KONFIGURACJA ==================\n#define TRYB_MOSFET          // moduły ESC sterowane PWM 20 kHz (domyślnie)\n// #define TRYB_ESC_RC       // albo regulatory ESC (impulsy 1000-2000 us)\n                             // Zostaw odkomentowany TYLKO JEDEN tryb!\n\nconst int PINY_SILNIKOW[4] = {18, 19, 20, 21};   // M1, M2, M3, M4\nconst int PIN_STOP = 9;          // przycisk BOOT = STOP awaryjny\nconst int PIN_SDA = 6;\nconst int PIN_SCL = 7;\nconst float MAX_MOC = 60;        // [%] tej mocy program nigdy nie przekroczy\nconst float RAMPA = 100;         // [% na sekundę] w locie trzeba szybciej\n\nconst int PWM_HZ = 20000;        // TRYB_MOSFET: częstotliwość PWM\nconst int PWM_BITY = 10;\nconst int ESC_HZ = 50;           // TRYB_ESC_RC: 50 impulsów na sekundę\nconst int ESC_BITY = 14;\n\n// Zabezpieczenia\nconst int WYSOKOSC_MAX = 800;            // [mm] wyżej = STOP\nconst unsigned long CZAS_MAX = 60000;    // [ms] najdłuższy lot (60 s)\nconst unsigned long BRAK_POMIARU_MS = 200;\nconst int WYSOKOSC_ZIEMI = 60;           // [mm] zadana niżej = lądujemy\nconst float SUMA_MAX = 10000;            // limit sumy błędów (anti-windup)\n\n// Nastawy na start (zmieniasz je komendami)\nfloat zadana_mm = 300;\nfloat moc_zawisu = 35;           // [%] moc, przy której dron prawie wisi\n// ZADANIE 1: gdy znajdziesz dobre Kp (komenda p), wpisz je tu,\n// żeby po restarcie nie szukać od nowa.\nfloat Kp = 0.02;\nfloat Ki = 0;\nfloat Kd = 0;\n// ==================================================\n\n#if defined(TRYB_MOSFET) && defined(TRYB_ESC_RC)\n#error \"Wybierz tylko jeden tryb: TRYB_MOSFET albo TRYB_ESC_RC\"\n#endif\n\n// ================== SILNIKI I BEZPIECZEŃSTWO ==================\n// Ta część jest taka sama we wszystkich lekcjach z silnikami.\n\nbool uzbrojony = false;                 // false = silniki zablokowane\nfloat moc_zadana[4] = {0, 0, 0, 0};     // [%] do tej mocy dążymy\nfloat moc_teraz[4] = {0, 0, 0, 0};      // [%] tyle jest teraz (po rampie)\nunsigned long czas_rampy = 0;\n\n// Dioda: czerwona = rozbrojony, zielona = uzbrojony.\nvoid pokazStan() {\n#ifdef RGB_BUILTIN\n  if (uzbrojony) rgbLedWrite(RGB_BUILTIN, 0, 30, 0);\n  else rgbLedWrite(RGB_BUILTIN, 30, 0, 0);\n#else\n  pinMode(LED_BUILTIN, OUTPUT);\n  digitalWrite(LED_BUILTIN, uzbrojony ? HIGH : LOW);\n#endif\n}\n\n// Pierwsza rzecz w setup(): wszystkie piny silników na 0.\nvoid silnikiNaZero() {\n  for (int i = 0; i < 4; i++) {\n    pinMode(PINY_SILNIKOW[i], OUTPUT);\n    digitalWrite(PINY_SILNIKOW[i], LOW);\n  }\n}\n\n// Wysyła moc [%] na silnik nr 0..3 (to M1..M4).\nvoid wyslijMoc(int nr, float moc) {\n  if (!uzbrojony) moc = 0;\n  moc = constrain(moc, 0, MAX_MOC);\n#ifdef TRYB_ESC_RC\n  float impuls_us = 1000 + moc * 10;    // 0% = 1000 us, 100% = 2000 us\n  uint32_t wypelnienie = impuls_us * ESC_HZ * (1 << ESC_BITY) / 1000000.0;\n#else\n  uint32_t wypelnienie = moc / 100.0 * ((1 << PWM_BITY) - 1);\n#endif\n  ledcWrite(PINY_SILNIKOW[nr], wypelnienie);\n}\n\n// Włącza PWM sprzętowy (LEDC) na pinach silników, z mocą 0.\nvoid silnikiStart() {\n  for (int i = 0; i < 4; i++) {\n#ifdef TRYB_ESC_RC\n    ledcAttach(PINY_SILNIKOW[i], ESC_HZ, ESC_BITY);\n#else\n    ledcAttach(PINY_SILNIKOW[i], PWM_HZ, PWM_BITY);\n#endif\n    wyslijMoc(i, 0);\n  }\n  pinMode(PIN_STOP, INPUT_PULLUP);\n  czas_rampy = millis();\n  pokazStan();\n}\n\n// RAMPA: moc zmienia się najwyżej o RAMPA % na sekundę.\nvoid rampa() {\n  float dt = (millis() - czas_rampy) / 1000.0;\n  czas_rampy = millis();\n  float krok = RAMPA * dt;\n  for (int i = 0; i < 4; i++) {\n    float cel = uzbrojony ? constrain(moc_zadana[i], 0, MAX_MOC) : 0;\n    if (moc_teraz[i] < cel) moc_teraz[i] = min(moc_teraz[i] + krok, cel);\n    else moc_teraz[i] = max(moc_teraz[i] - krok, cel);\n    wyslijMoc(i, moc_teraz[i]);\n  }\n}\n\nvoid ustawWszystkie(float moc) {\n  for (int i = 0; i < 4; i++) moc_zadana[i] = constrain(moc, 0, MAX_MOC);\n}\n\nvoid uzbroj() {\n  uzbrojony = true;\n  Serial.println(\"UZBROJONY! Uwaga na śmigła.\");\n  pokazStan();\n}\n\n// STOP: od razu wyłącza wszystkie silniki i mówi dlaczego.\nvoid stop(String powod) {\n  uzbrojony = false;\n  for (int i = 0; i < 4; i++) {\n    moc_zadana[i] = 0;\n    moc_teraz[i] = 0;\n    wyslijMoc(i, 0);\n  }\n  Serial.println(\"STOP! Powód: \" + powod);\n  pokazStan();\n}\n\nvoid sprawdzPrzycisk() {\n  if (uzbrojony && digitalRead(PIN_STOP) == LOW) stop(\"przycisk BOOT\");\n}\n\n// ================== KOMENDY Z SERIAL MONITORA ==================\n// Ta sama funkcja we wszystkich lekcjach. Czyta linię, np. \"p 0.05\":\n// litera trafia do komenda, liczba do komenda_liczba.\n// Sama liczba (np. \"40\") to komenda 'm'. \"x\" i spacja działają od razu.\nchar komenda = 0;\nfloat komenda_liczba = 0;\nString linia = \"\";\n\nbool czytajKomende() {\n  while (Serial.available() > 0) {\n    char znak = Serial.read();\n    if (linia.length() == 0 && (znak == 'x' || znak == 'X' || znak == ' ')) {\n      komenda = 'x';\n      return true;\n    }\n    if (znak == '\\n' || znak == '\\r') {\n      if (linia.length() == 0) continue;\n      komenda = linia.charAt(0);\n      if (isDigit(komenda)) {\n        komenda = 'm';\n        komenda_liczba = linia.toFloat();\n      } else {\n        komenda_liczba = linia.substring(1).toFloat();\n      }\n      linia = \"\";\n      return true;\n    }\n    linia += znak;\n  }\n  return false;\n}\n\n// ================== LASER ==================\nVL53L1X laser;\nfloat wysokosc_mm = 0;\nunsigned long czas_pomiaru = 0;          // kiedy był ostatni dobry pomiar\n\nbool laserStart() {\n  Wire.begin(PIN_SDA, PIN_SCL);\n  Wire.setClock(100000);   // 100 kHz: kabel I2C ma ok. 1 m, więc wolniej i pewniej\n  Wire.setTimeOut(50);     // nie czekaj w nieskończoność, gdy czujnik milczy\n  laser.setTimeout(500);\n  if (!laser.init()) return false;\n  laser.setDistanceMode(VL53L1X::Short);\n  laser.setMeasurementTimingBudget(33000);\n  laser.startContinuous(33);\n  return true;\n}\n\n// Czy ostatni pomiar jest dobry? (statusy z „RangeValid” w nazwie)\nbool dobryPomiar() {\n  int s = laser.ranging_data.range_status;\n  return s == VL53L1X::RangeValid || s == VL53L1X::RangeValidMinRangeClipped ||\n         s == VL53L1X::RangeValidNoWrapCheckFail;\n}\n\n// ================== REGULATOR ==================\nfloat suma_bledow = 0;\nfloat poprzedni_blad = 0;\nbool pierwszy_krok = true;\nunsigned long czas_uzbrojenia = 0;\n\nvoid regulator() {\n  if (!uzbrojony) return;\n  if (zadana_mm < WYSOKOSC_ZIEMI) {      // lądowanie: silniki płynnie do 0\n    ustawWszystkie(0);\n    suma_bledow = 0;\n    pierwszy_krok = true;\n    return;\n  }\n  float blad = zadana_mm - wysokosc_mm;\n  if (pierwszy_krok) {\n    poprzedni_blad = blad;\n    pierwszy_krok = false;\n  }\n  suma_bledow = constrain(suma_bledow + blad, -SUMA_MAX, SUMA_MAX);\n  float zmiana_bledu = blad - poprzedni_blad;\n  poprzedni_blad = blad;\n\n  // ZADANIE 2: dopisz do wzoru  + Ki * suma_bledow\n  // ZADANIE 3: dopisz do wzoru  + Kd * zmiana_bledu\n  float moc = moc_zawisu + Kp * blad;\n  ustawWszystkie(moc);   // ustawWszystkie pilnuje zakresu 0..MAX_MOC\n}\n\n// Automatyczny STOP, gdy coś jest nie tak.\nvoid bezpieczenstwo() {\n  if (!uzbrojony) return;\n  if (millis() - czas_pomiaru > BRAK_POMIARU_MS) stop(\"brak pomiaru z lasera dłużej niż 200 ms\");\n  else if (wysokosc_mm > WYSOKOSC_MAX) stop(\"za wysoko (powyżej WYSOKOSC_MAX)\");\n  else if (millis() - czas_uzbrojenia > CZAS_MAX) stop(\"minął CZAS_MAX lotu\");\n}\n\nvoid wypiszNastawy() {\n  Serial.println(\"zadana_mm=\" + String(zadana_mm) + \"  moc_zawisu=\" + String(moc_zawisu) +\n                 \"  Kp=\" + String(Kp, 4) + \"  Ki=\" + String(Ki, 4) + \"  Kd=\" + String(Kd, 4));\n}\n\n// ================== PROGRAM LEKCJI ==================\nvoid obsluzKomende() {\n  if (komenda == 'x') {\n    stop(\"komenda x\");\n  } else if (komenda == 'u') {\n    if (millis() - czas_pomiaru > BRAK_POMIARU_MS) {\n      Serial.println(\"Nie uzbrajam: brak pomiaru z lasera.\");\n      return;\n    }\n    suma_bledow = 0;\n    pierwszy_krok = true;\n    czas_uzbrojenia = millis();\n    uzbroj();\n  } else if (komenda == 'h') {\n    float nowa = constrain(komenda_liczba, 0, WYSOKOSC_MAX - 100);\n    poprzedni_blad += nowa - zadana_mm;  // żeby Kd nie „szarpnął” przy zmianie\n    zadana_mm = nowa;\n  } else if (komenda == 'p') {\n    Kp = komenda_liczba;\n  } else if (komenda == 'i') {\n    Ki = komenda_liczba;\n  } else if (komenda == 'd') {\n    Kd = komenda_liczba;\n  } else if (komenda == 'z') {\n    moc_zawisu = constrain(komenda_liczba, 0, MAX_MOC);\n  } else if (komenda != '?') {\n    Serial.println(\"Znam komendy: u, x, h, p, i, d, z, ?\");\n  }\n  wypiszNastawy();\n}\n\nvoid setup() {\n  silnikiNaZero();           // NAJPIERW silniki na 0!\n  Serial.begin(115200);\n  delay(1000);\n  silnikiStart();\n  while (!laserStart()) {\n    Serial.println(\"Nie widzę lasera! Uruchom skaner L02. Widzi 0x29? To może być inny model czujnika – zawołaj prowadzącego.\");\n    delay(2000);\n  }\n  Serial.println(\"L09: trzymaj wysokość. Wpisz u, potem h 300.\");\n  wypiszNastawy();\n}\n\nvoid loop() {\n  if (czytajKomende()) obsluzKomende();\n  sprawdzPrzycisk();\n\n  if (laser.dataReady()) {               // nowy pomiar = jeden krok regulatora\n    laser.read(false);\n    if (dobryPomiar()) {\n      wysokosc_mm = laser.ranging_data.range_mm;\n      czas_pomiaru = millis();\n      regulator();\n      Serial.print(\"zadana:\");\n      Serial.print(zadana_mm);\n      Serial.print(\",wysokosc:\");\n      Serial.print(wysokosc_mm);\n      Serial.print(\",moc_x10:\");         // moc × 10, żeby było ją widać obok mm\n      Serial.println(moc_teraz[0] * 10);\n    }\n  }\n\n  bezpieczenstwo();\n  rampa();\n}\n",
 "uczen/L10_misja": "/*\n * ==============================================================\n *  LEKCJA 10: MISJA – ZAWODY!\n *  Kurs „Inżynieria dronowa” – Uniwersytet Dzieci, zajęcia 5\n *  WERSJA UCZNIA\n * ==============================================================\n *\n *  CZEGO SIĘ NAUCZYSZ\n *   - Co to jest MASZYNA STANÓW.\n *   - Jak zaplanować lot jako listę kroków (tablicę).\n *\n *  CO MUSI BYĆ PODŁĄCZONE\n *   - Tak jak w L09: dron na prowadnicy, silniki, laser w dół.\n *\n *  JAK TO DZIAŁA\n *   Maszyna stanów: dron jest zawsze w JEDNYM stanie, jak postać\n *   w grze (stoi / skacze / biegnie). Coś się dzieje -> zmiana stanu.\n *\n *    CZEKAJ --\"s\"--> START --2 s--> MISJA --kroki gotowe--> LĄDOWANIE\n *      ^                           (krok 1, 2, 3 ...)           |\n *      |                                                        v\n *      +------------- STOP (x, BOOT, zabezpieczenia) <------ KONIEC\n *\n *   MISJA bierze kolejne kroki z tablicy KROKI:\n *     {wysokość w mm, czas w ms}  – „leć na tę wysokość i trzymaj”.\n *   Wysokość zadana nie skacze, tylko płynnie „jedzie” do celu.\n *   Wysokość trzyma ten sam regulator PID co w L09.\n *\n *  BEZPIECZEŃSTWO (jak w L09)\n *   - Start ROZBROJONY (czerwona). \"u\" = uzbrój (zielona).\n *   - \"x\" albo spacja = STOP. Przycisk BOOT = STOP.\n *   - Automatyczny STOP: brak pomiaru > 200 ms, wysokość > WYSOKOSC_MAX,\n *     lot dłuższy niż CZAS_MAX.\n *\n *  KOMENDY\n *   u – uzbrój     s – start misji     x – STOP     ? – nastawy\n *   p, i, d, z – nastawy regulatora (jak w L09)\n *\n *  ZADANIE (szukaj w kodzie napisu ZADANIE)\n *   1. Zaplanuj misję: zmień TYLKO tablicę KROKI.\n */\n\n#include <Wire.h>\n#include <VL53L1X.h>\n\n// ================== MISJA ==================\n// ZADANIE 1: zaplanuj misję. Każda linijka to jeden krok:\n//   {wysokość w mm, czas w ms},\n// Wysokość: od 100 do 700 mm. Cała misja musi trwać krócej niż 60 s.\n// Możesz dopisać więcej linijek.\nconst int KROKI[][2] = {\n  {200, 3000},\n  {300, 3000},\n};\nconst int ILE_KROKOW = sizeof(KROKI) / sizeof(KROKI[0]);   // liczy się samo\n\n// ================== KONFIGURACJA ==================\n#define TRYB_MOSFET          // moduły ESC sterowane PWM 20 kHz (domyślnie)\n// #define TRYB_ESC_RC       // albo regulatory ESC (impulsy 1000-2000 us)\n                             // Zostaw odkomentowany TYLKO JEDEN tryb!\n\nconst int PINY_SILNIKOW[4] = {18, 19, 20, 21};   // M1, M2, M3, M4\nconst int PIN_STOP = 9;          // przycisk BOOT = STOP awaryjny\nconst int PIN_SDA = 6;\nconst int PIN_SCL = 7;\nconst float MAX_MOC = 60;        // [%] tej mocy program nigdy nie przekroczy\nconst float RAMPA = 100;         // [% na sekundę]\n\nconst int PWM_HZ = 20000;        // TRYB_MOSFET: częstotliwość PWM\nconst int PWM_BITY = 10;\nconst int ESC_HZ = 50;           // TRYB_ESC_RC: 50 impulsów na sekundę\nconst int ESC_BITY = 14;\n\n// Zabezpieczenia\nconst int WYSOKOSC_MAX = 800;            // [mm] wyżej = STOP\nconst unsigned long CZAS_MAX = 60000;    // [ms] najdłuższy lot (60 s)\nconst unsigned long BRAK_POMIARU_MS = 200;\nconst int WYSOKOSC_ZIEMI = 60;           // [mm] zadana niżej = silniki stop\nconst float SUMA_MAX = 10000;            // limit sumy błędów (anti-windup)\n\n// Start i lądowanie\nconst int WYSOKOSC_STARTU = 150;         // [mm] na tę wysokość wzlatujemy\nconst unsigned long CZAS_STARTU_MS = 2000;\nconst float PREDKOSC_ZADANEJ = 150;      // [mm/s] jak szybko „jedzie” zadana\n\n// Nastawy regulatora – wpiszcie te z L09\nfloat moc_zawisu = 35;\nfloat Kp = 0.05;\nfloat Ki = 0.002;\nfloat Kd = 0.5;\n// ==================================================\n\n#if defined(TRYB_MOSFET) && defined(TRYB_ESC_RC)\n#error \"Wybierz tylko jeden tryb: TRYB_MOSFET albo TRYB_ESC_RC\"\n#endif\n\n// ================== SILNIKI I BEZPIECZEŃSTWO ==================\n// Ta część jest taka sama we wszystkich lekcjach z silnikami.\n\nbool uzbrojony = false;                 // false = silniki zablokowane\nfloat moc_zadana[4] = {0, 0, 0, 0};     // [%] do tej mocy dążymy\nfloat moc_teraz[4] = {0, 0, 0, 0};      // [%] tyle jest teraz (po rampie)\nunsigned long czas_rampy = 0;\n\n// Dioda: czerwona = rozbrojony, zielona = uzbrojony.\nvoid pokazStan() {\n#ifdef RGB_BUILTIN\n  if (uzbrojony) rgbLedWrite(RGB_BUILTIN, 0, 30, 0);\n  else rgbLedWrite(RGB_BUILTIN, 30, 0, 0);\n#else\n  pinMode(LED_BUILTIN, OUTPUT);\n  digitalWrite(LED_BUILTIN, uzbrojony ? HIGH : LOW);\n#endif\n}\n\n// Pierwsza rzecz w setup(): wszystkie piny silników na 0.\nvoid silnikiNaZero() {\n  for (int i = 0; i < 4; i++) {\n    pinMode(PINY_SILNIKOW[i], OUTPUT);\n    digitalWrite(PINY_SILNIKOW[i], LOW);\n  }\n}\n\n// Wysyła moc [%] na silnik nr 0..3 (to M1..M4).\nvoid wyslijMoc(int nr, float moc) {\n  if (!uzbrojony) moc = 0;\n  moc = constrain(moc, 0, MAX_MOC);\n#ifdef TRYB_ESC_RC\n  float impuls_us = 1000 + moc * 10;    // 0% = 1000 us, 100% = 2000 us\n  uint32_t wypelnienie = impuls_us * ESC_HZ * (1 << ESC_BITY) / 1000000.0;\n#else\n  uint32_t wypelnienie = moc / 100.0 * ((1 << PWM_BITY) - 1);\n#endif\n  ledcWrite(PINY_SILNIKOW[nr], wypelnienie);\n}\n\n// Włącza PWM sprzętowy (LEDC) na pinach silników, z mocą 0.\nvoid silnikiStart() {\n  for (int i = 0; i < 4; i++) {\n#ifdef TRYB_ESC_RC\n    ledcAttach(PINY_SILNIKOW[i], ESC_HZ, ESC_BITY);\n#else\n    ledcAttach(PINY_SILNIKOW[i], PWM_HZ, PWM_BITY);\n#endif\n    wyslijMoc(i, 0);\n  }\n  pinMode(PIN_STOP, INPUT_PULLUP);\n  czas_rampy = millis();\n  pokazStan();\n}\n\n// RAMPA: moc zmienia się najwyżej o RAMPA % na sekundę.\nvoid rampa() {\n  float dt = (millis() - czas_rampy) / 1000.0;\n  czas_rampy = millis();\n  float krok = RAMPA * dt;\n  for (int i = 0; i < 4; i++) {\n    float cel = uzbrojony ? constrain(moc_zadana[i], 0, MAX_MOC) : 0;\n    if (moc_teraz[i] < cel) moc_teraz[i] = min(moc_teraz[i] + krok, cel);\n    else moc_teraz[i] = max(moc_teraz[i] - krok, cel);\n    wyslijMoc(i, moc_teraz[i]);\n  }\n}\n\nvoid ustawWszystkie(float moc) {\n  for (int i = 0; i < 4; i++) moc_zadana[i] = constrain(moc, 0, MAX_MOC);\n}\n\nvoid uzbroj() {\n  uzbrojony = true;\n  Serial.println(\"UZBROJONY! Uwaga na śmigła.\");\n  pokazStan();\n}\n\n// STOP: od razu wyłącza wszystkie silniki i mówi dlaczego.\nvoid stop(String powod) {\n  uzbrojony = false;\n  for (int i = 0; i < 4; i++) {\n    moc_zadana[i] = 0;\n    moc_teraz[i] = 0;\n    wyslijMoc(i, 0);\n  }\n  Serial.println(\"STOP! Powód: \" + powod);\n  pokazStan();\n}\n\nvoid sprawdzPrzycisk() {\n  if (uzbrojony && digitalRead(PIN_STOP) == LOW) stop(\"przycisk BOOT\");\n}\n\n// ================== KOMENDY Z SERIAL MONITORA ==================\n// Ta sama funkcja we wszystkich lekcjach. Czyta linię, np. \"p 0.05\":\n// litera trafia do komenda, liczba do komenda_liczba.\n// Sama liczba (np. \"40\") to komenda 'm'. \"x\" i spacja działają od razu.\nchar komenda = 0;\nfloat komenda_liczba = 0;\nString linia = \"\";\n\nbool czytajKomende() {\n  while (Serial.available() > 0) {\n    char znak = Serial.read();\n    if (linia.length() == 0 && (znak == 'x' || znak == 'X' || znak == ' ')) {\n      komenda = 'x';\n      return true;\n    }\n    if (znak == '\\n' || znak == '\\r') {\n      if (linia.length() == 0) continue;\n      komenda = linia.charAt(0);\n      if (isDigit(komenda)) {\n        komenda = 'm';\n        komenda_liczba = linia.toFloat();\n      } else {\n        komenda_liczba = linia.substring(1).toFloat();\n      }\n      linia = \"\";\n      return true;\n    }\n    linia += znak;\n  }\n  return false;\n}\n\n// ================== LASER ==================\nVL53L1X laser;\nfloat wysokosc_mm = 0;\nunsigned long czas_pomiaru = 0;\n\nbool laserStart() {\n  Wire.begin(PIN_SDA, PIN_SCL);\n  Wire.setClock(100000);   // 100 kHz: kabel I2C ma ok. 1 m, więc wolniej i pewniej\n  Wire.setTimeOut(50);     // nie czekaj w nieskończoność, gdy czujnik milczy\n  laser.setTimeout(500);\n  if (!laser.init()) return false;\n  laser.setDistanceMode(VL53L1X::Short);\n  laser.setMeasurementTimingBudget(33000);\n  laser.startContinuous(33);\n  return true;\n}\n\nbool dobryPomiar() {\n  int s = laser.ranging_data.range_status;\n  return s == VL53L1X::RangeValid || s == VL53L1X::RangeValidMinRangeClipped ||\n         s == VL53L1X::RangeValidNoWrapCheckFail;\n}\n\n// ================== REGULATOR (jak w L09) ==================\nfloat zadana_mm = 0;\nfloat suma_bledow = 0;\nfloat poprzedni_blad = 0;\nbool pierwszy_krok = true;\nunsigned long czas_uzbrojenia = 0;\n\nvoid regulator() {\n  if (!uzbrojony) return;\n  if (zadana_mm < WYSOKOSC_ZIEMI) {      // przy ziemi: silniki płynnie do 0\n    ustawWszystkie(0);\n    suma_bledow = 0;\n    pierwszy_krok = true;\n    return;\n  }\n  float blad = zadana_mm - wysokosc_mm;\n  if (pierwszy_krok) {\n    poprzedni_blad = blad;\n    pierwszy_krok = false;\n  }\n  suma_bledow = constrain(suma_bledow + blad, -SUMA_MAX, SUMA_MAX);\n  float zmiana_bledu = blad - poprzedni_blad;\n  poprzedni_blad = blad;\n  float moc = moc_zawisu + Kp * blad + Ki * suma_bledow + Kd * zmiana_bledu;\n  ustawWszystkie(moc);\n}\n\nvoid bezpieczenstwo() {\n  if (!uzbrojony) return;\n  if (millis() - czas_pomiaru > BRAK_POMIARU_MS) stop(\"brak pomiaru z lasera dłużej niż 200 ms\");\n  else if (wysokosc_mm > WYSOKOSC_MAX) stop(\"za wysoko (powyżej WYSOKOSC_MAX)\");\n  else if (millis() - czas_uzbrojenia > CZAS_MAX) stop(\"minął CZAS_MAX lotu\");\n}\n\nvoid wypiszNastawy() {\n  Serial.println(\"moc_zawisu=\" + String(moc_zawisu) + \"  Kp=\" + String(Kp, 4) +\n                 \"  Ki=\" + String(Ki, 4) + \"  Kd=\" + String(Kd, 4));\n}\n\n// ================== MASZYNA STANÓW ==================\nconst int CZEKAJ = 0;\nconst int START = 1;\nconst int MISJA = 2;\nconst int LADOWANIE = 3;\nconst int KONIEC = 4;\nconst String NAZWY_STANOW[5] = {\"CZEKAJ\", \"START\", \"MISJA\", \"LĄDOWANIE\", \"KONIEC\"};\n\nint stan = CZEKAJ;\nunsigned long czas_stanu = 0;    // kiedy weszliśmy w obecny stan\nunsigned long czas_startu = 0;   // kiedy zaczęła się misja\nint krok = 0;                    // który krok misji (od 0)\nfloat cel_mm = 0;                // dokąd „jedzie” zadana\n\nvoid zmienStan(int nowy) {\n  stan = nowy;\n  czas_stanu = millis();\n  Serial.println(\"STAN -> \" + NAZWY_STANOW[nowy]);\n}\n\n// Ile ms potrwa cała misja (start + kroki + zapas na lądowanie).\nunsigned long czasMisji() {\n  unsigned long suma = CZAS_STARTU_MS + 5000;\n  for (int i = 0; i < ILE_KROKOW; i++) suma += KROKI[i][1];\n  return suma;\n}\n\n// Wołana przy każdym pomiarze: decyduje, co robić dalej.\nvoid maszynaStanow() {\n  unsigned long w_stanie = millis() - czas_stanu;\n\n  if (stan == START) {\n    cel_mm = WYSOKOSC_STARTU;\n    if (w_stanie > CZAS_STARTU_MS) {\n      krok = 0;\n      zmienStan(MISJA);\n    }\n  } else if (stan == MISJA) {\n    cel_mm = constrain(KROKI[krok][0], 0, WYSOKOSC_MAX - 100);\n    if (w_stanie > (unsigned long)KROKI[krok][1]) {\n      krok++;\n      czas_stanu = millis();\n      if (krok >= ILE_KROKOW) zmienStan(LADOWANIE);\n      else Serial.println(\"KROK \" + String(krok + 1) + \" z \" + String(ILE_KROKOW));\n    }\n  } else if (stan == LADOWANIE) {\n    cel_mm = 0;\n    if (zadana_mm < WYSOKOSC_ZIEMI) zmienStan(KONIEC);\n  } else if (stan == KONIEC) {\n    ustawWszystkie(0);\n    if (uzbrojony && moc_teraz[0] == 0) {   // silniki już stanęły\n      uzbrojony = false;\n      pokazStan();\n      Serial.println(\"MISJA ZAKOŃCZONA! Czas: \" + String((millis() - czas_startu) / 1000.0) + \" s\");\n    }\n  }\n\n  // Zadana płynnie „jedzie” do celu, najwyżej PREDKOSC_ZADANEJ mm/s.\n  float krok_mm = PREDKOSC_ZADANEJ * 0.033;\n  if (zadana_mm < cel_mm) zadana_mm = min(zadana_mm + krok_mm, cel_mm);\n  else zadana_mm = max(zadana_mm - krok_mm, cel_mm);\n\n  if (stan != KONIEC) regulator();\n}\n\n// ================== PROGRAM LEKCJI ==================\nvoid obsluzKomende() {\n  if (komenda == 'x') {\n    stop(\"komenda x\");\n  } else if (komenda == 'u') {\n    if (millis() - czas_pomiaru > BRAK_POMIARU_MS) {\n      Serial.println(\"Nie uzbrajam: brak pomiaru z lasera.\");\n      return;\n    }\n    czas_uzbrojenia = millis();\n    zmienStan(CZEKAJ);\n    uzbroj();\n  } else if (komenda == 's') {\n    if (!uzbrojony || stan != CZEKAJ) {\n      Serial.println(\"Start tylko w stanie CZEKAJ i po uzbrojeniu (u).\");\n    } else if (czasMisji() > CZAS_MAX) {\n      Serial.println(\"Misja za długa! Skróć czasy w tablicy KROKI.\");\n    } else {\n      zadana_mm = wysokosc_mm;          // zaczynamy od tego, gdzie jesteśmy\n      suma_bledow = 0;\n      pierwszy_krok = true;\n      czas_uzbrojenia = millis();\n      czas_startu = millis();\n      zmienStan(START);\n    }\n  } else if (komenda == 'p') {\n    Kp = komenda_liczba;\n  } else if (komenda == 'i') {\n    Ki = komenda_liczba;\n  } else if (komenda == 'd') {\n    Kd = komenda_liczba;\n  } else if (komenda == 'z') {\n    moc_zawisu = constrain(komenda_liczba, 0, MAX_MOC);\n  } else if (komenda != '?') {\n    Serial.println(\"Znam komendy: u, s, x, p, i, d, z, ?\");\n  }\n  if (komenda == 'p' || komenda == 'i' || komenda == 'd' || komenda == 'z' || komenda == '?') {\n    wypiszNastawy();\n  }\n}\n\nvoid setup() {\n  silnikiNaZero();           // NAJPIERW silniki na 0!\n  Serial.begin(115200);\n  delay(1000);\n  silnikiStart();\n  while (!laserStart()) {\n    Serial.println(\"Nie widzę lasera! Uruchom skaner L02. Widzi 0x29? To może być inny model czujnika – zawołaj prowadzącego.\");\n    delay(2000);\n  }\n  Serial.println(\"L10: misja. Kroków: \" + String(ILE_KROKOW) +\n                 \", potrwa ok. \" + String(czasMisji() / 1000) + \" s. Wpisz u, potem s.\");\n  wypiszNastawy();\n}\n\nvoid loop() {\n  if (czytajKomende()) obsluzKomende();\n  sprawdzPrzycisk();\n\n  if (laser.dataReady()) {\n    laser.read(false);\n    if (dobryPomiar()) {\n      wysokosc_mm = laser.ranging_data.range_mm;\n      czas_pomiaru = millis();\n      if (stan != CZEKAJ) maszynaStanow();\n      Serial.print(\"zadana:\");\n      Serial.print(zadana_mm);\n      Serial.print(\",wysokosc:\");\n      Serial.print(wysokosc_mm);\n      Serial.print(\",moc_x10:\");\n      Serial.print(moc_teraz[0] * 10);\n      Serial.print(\",stan_x100:\");\n      Serial.println(stan * 100);\n    }\n  }\n\n  bezpieczenstwo();\n  // Po STOP (x, BOOT albo zabezpieczenie) wracamy do CZEKAJ.\n  if (!uzbrojony && stan != CZEKAJ && stan != KONIEC) zmienStan(CZEKAJ);\n  rampa();\n}\n"
};
